#include "window.h"
#include "driver_packages.h"
QWidget *MainWindow::dependenciesControls(){auto *box=new QGroupBox("Dependências do aplicativo");auto *layout=new QVBoxLayout(box);auto *install=new QPushButton("Instalar dependências");auto *state=new QLabel("Detectar a distribuição e revisar os pacotes antes de instalar. Não instala drivers, não adiciona repositórios e não cria sensores ausentes.");state->setWordWrap(true);layout->addWidget(state);layout->addWidget(install);install->setEnabled(!offline);connect(install,&QPushButton::clicked,this,[this,install,state]{if(offline||testActive||driverBusy||displayBusy||codecSuite.busy()||clockProcess.state()!=QProcess::NotRunning)return;QFile embedded(":/tools/install-dependencies.sh");if(!embedded.open(QIODevice::ReadOnly)){state->setText("Script de dependências ausente no pacote.");return;}const QByteArray script=embedded.readAll();const QString directory=configRoot()+"/dependency-tools";QDir().mkpath(directory);const QString path=directory+"/install-"+QCryptographicHash::hash(script,QCryptographicHash::Sha256).toHex()+".sh";QSaveFile saved(path);if(!saved.open(QIODevice::WriteOnly)||saved.write(script)!=script.size()||!saved.commit()){state->setText("Não foi possível preparar o script.");return;}auto *process=new QProcess(this);process->setProcessEnvironment(nativeEnvironment());auto *timeout=new QTimer(process);timeout->setSingleShot(true);timeout->setInterval(30000);connect(timeout,&QTimer::timeout,process,&QProcess::kill);install->setEnabled(false);connect(process,qOverload<int,QProcess::ExitStatus>(&QProcess::finished),this,[this,process,timeout,install,state](int,QProcess::ExitStatus){timeout->stop();install->setEnabled(true);const auto bytes=process->readAllStandardOutput();const auto plan=QJsonDocument::fromJson(bytes).object();const auto error=QString::fromUtf8(process->readAllStandardError());process->deleteLater();if(!plan["ok"].toBool()){state->setText(plan["error"].toString("Falha ao identificar dependências: "+error));return;}QStringList command;for(auto v:plan["command"].toArray())command<<v.toString();if(command.isEmpty()){state->setText("Plano vazio; nada foi executado.");return;}const QString description="Sistema: "+plan["system"].toString()+"\n"+plan["note"].toString()+"\n\n"+command.join(' ');state->setText(description);if(QMessageBox::question(this,"Instalar dependências",description+"\n\nAbrir o gerenciador nativo para revisar e instalar?",QMessageBox::Yes|QMessageBox::No,QMessageBox::No)!=QMessageBox::Yes)return;startNativeTransaction(command,[this,state](int code){state->setText(code==0?"Gerenciador concluído. Reabra o aplicativo e confira as dependências e os sensores.":"Instalação não confirmada. Confira o terminal e os repositórios da distribuição.");log("Instalação de dependências: código "+QString::number(code));});});connect(process,&QProcess::errorOccurred,this,[process,install,state](QProcess::ProcessError e){if(e==QProcess::FailedToStart){install->setEnabled(true);state->setText(process->errorString());process->deleteLater();}});timeout->start();process->start("/bin/sh",{path,"--plan"});});return box;}
